p=Path(__file__).parent
base='''<svg xmlns="http://www.w3.org/2000/svg" width="1024" height="1024" viewBox="0 0 1024 1024"><defs><linearGradient id="bg" x2=".85" y2="1"><stop stop-color="{a}"/><stop offset=".52" stop-color="{b}"/><stop offset="1" stop-color="{c}"/></linearGradient><linearGradient id="glass" x2=".6" y2="1"><stop stop-color="white" stop-opacity=".9"/><stop offset="1" stop-color="#dcf5ff" stop-opacity=".35"/></linearGradient><filter id="shadow" x="-30%" y="-30%" width="160%" height="170%"><feDropShadow dy="14" stdDeviation="12" flood-color="#122e71" flood-opacity=".25"/></filter></defs><rect x="100" y="100" width="824" height="824" rx="184" fill="url(#bg)"/><rect x="103" y="103" width="818" height="818" rx="181" fill="none" stroke="white" stroke-opacity=".45" stroke-width="6"/><path d="M150 350 Q180 130 390 130 H710 Q850 130 880 280 Q600 180 150 350" fill="white" opacity=".12"/>{content}</svg>'''
