variants=[('01-clean-display','#49d8ed','#247eea','#6054cc','''<g filter="url(#shadow)"><rect x="244" y="284" width="536" height="370" rx="48" fill="url(#glass)" stroke="white" stroke-width="12"/><rect x="273" y="314" width="478" height="308" rx="25" fill="#1462a6" fill-opacity=".65"/><path d="M460 660 L448 714 H576 L564 660 M390 730 H634" fill="none" stroke="#e9faff" stroke-width="28" stroke-linecap="round"/><path d="M332 560 L468 424 L612 560 L476 654Z" fill="#b7f4ff" stroke="white" stroke-width="8"/><path d="M364 557 L472 449" stroke="white" stroke-opacity=".5" stroke-width="10" stroke-linecap="round"/></g>'''+spark),('02-clean-shield','#8c83ec','#447de0','#20b7cf','''<g filter="url(#shadow)"><path d="M512 245 Q620 305 728 320 V498 Q728 670 512 780 Q296 670 296 498 V320 Q404 305 512 245Z" fill="url(#glass)" stroke="white" stroke-opacity=".9" stroke-width="12"/><path d="M512 282 Q610 333 692 347 V496 Q692 640 512 737 Q332 640 332 496 V347 Q414 333 512 282Z" fill="#245bb8" fill-opacity=".44"/><path d="M445 487 V437 A67 67 0 0 1 579 437 V487" fill="none" stroke="white" stroke-width="30" stroke-linecap="round"/><rect x="406" y="479" width="212" height="163" rx="34" fill="url(#glass)" stroke="white" stroke-width="7"/><circle cx="512" cy="548" r="18" fill="#2864b6"/><path d="M512 549 V582" stroke="#2864b6" stroke-width="18" stroke-linecap="round"/></g>'''+spark),('03-glass-key','#36cde0','#168ee3','#4057c7','''<g filter="url(#shadow)"><rect x="277" y="277" width="470" height="470" rx="112" fill="url(#glass)" stroke="white" stroke-width="12"/><rect x="314" y="314" width="396" height="396" rx="83" fill="#156ebc" fill-opacity=".4" stroke="white" stroke-opacity=".35" stroke-width="4"/><path d="M510 358 Q526 490 650 510 Q526 530 510 662 Q494 530 370 510 Q494 490 510 358Z" fill="white"/><path d="M655 340 Q660 378 696 383 Q660 388 655 426 Q650 388 614 383 Q650 378 655 340Z" fill="white"/></g>''')]
for name,a,b,c,content in variants:
 s=base.replace('{a}',a).replace('{b}',b).replace('{c}',c).replace('{content}',content)
 (p/(name+'.svg')).write_text(s)
 for size in (1024,64,16):
  subprocess.run(['rsvg-convert','-w',str(size),'-h',str(size),str(p/(name+'.svg')),'-o',str(p/(name+f'-{size}.png'))],check=True)
